type EffectControlBase = {
  /** Mandatory spatial contract: geometric transforms, unchanged geometry, or pixel analysis required. */
  spatial: "analytic" | "geometry_preserving" | "pixel_dependent";
  prop:
    | "sticker_outline_width" | "media_orientation" | "media_mirror" | "subject_flash" | "subject_glow" | "subject_glow_radius" | "media_blend_mode" | "media_scale" | "media_offset_x" | "media_offset_y" | "media_opacity"
    | "window_side_margin_percent" | "window_vertical_margin_percent" | "window_center_y_percent" | "window_open_duration" | "window_corner_radius" | "mask_inset" | "mask_feather" | "mask_corner_radius" | "iris_radius" | "iris_feather" | "zoom_blur" | "transition_blur" | "directional_blur_x" | "directional_blur_y"
    | GridMatteField
    | SubjectWindowNumberField | "subject_window_mode"
    | ColorGradeField
    | AdvancedColorGradeField
    | ChromaKeyAmountField
    | GradientMapField
    | GlitchField
    | FilmLookField
    | "chroma_key_color" | "paper_fill_color" | "recolor_color" | "recolor_amount" | "recolor_preserve_shading";
  label: string;
  /** What the label and range cannot say to an agent: direction, order or sign. Joined into the field's tool description. */
  agentHint?: string;
  /**
   * Whether the field can carry keyframes. A chroma key colour deliberately
   * cannot: the colour is a fact about how the clip was shot, not a motion.
   */
  keyframeable: boolean;
  resolver:
    | "GridMatte" | "SubjectWindow" | "resolveStickerOutline" | "SubjectGlowFilter" | "mediaBlendStyle" | "resolveTransitionEffects" | "resolveMediaTransformAtTime" | "resolveMaskInsetAtTime" | "resolveMediaEffectAtTime"
    | "resolveColorGradeAtTime" | "resolveChromaKeyAtTime" | "paperFillFilter" | "RecolorFilter" | "resolveGradientMapAtTime" | "resolveGlitchAtTime" | "resolveFilmLookAtTime";
  renderer: "GradientMapFilter" | "GlitchFilter" | "FilmLookFilter" | "GridMatte" | "SubjectWindow" | "StickerOutlineFilter" | "SubjectGlowFilter" | "mediaBlendStyle" | "MediaTransformFrame" | "ColorGradeFilter" | "chromaKeyEffects" | "mediaDropShadowStyle" | "RecolorFilter";
  uiControl:
    | "select" | "percent-scrubber" | "normalized-scrubber" | "scale-scrubber" | "mask-edges"
    | "grade-scrubber" | "unit-scrubber" | "color-swatch"
    | "grade-wheel" | "grade-curve" | "grade-slice";
  ui: {
    component: "ClipLookControls" | "ColorGradeAdvancedControls" | "GridMatteControls" | "SubjectWindowControls" | "CutoutEffectControls" | "SubjectGlowControls" | "ElementMenu" | "TransitionEffectControls";
    previewCallback: "preview" | "onPreview" | "onPatch" | "previewVisualTransform" | "previewMaskInset" | "previewMediaEffect" | "previewColorGrade" | "previewChromaKey" | "patchSelectedElementProps";
    commitCallback: "commit" | "onPatch" | "commitVisualTransform" | "commitMaskInset" | "commitMediaEffect" | "commitColorGrade" | "commitChromaKey" | "patchSelectedElementProps";
    resetCallback: "onReset" | "onPatch" | "resetVisualTransform" | "resetMaskInset" | "resetMediaEffects" | "resetColorGradeControls" | "resetChromaKeyControls" | "patchSelectedElementProps";
    /** Present exactly when `keyframeable` is true. */
    keyframeCallback?: "toggleKeyframe" | "toggleOutlineKeyframe" | "toggleTransitionKeyframe" | "addTransformKeyframeAtPlayhead" | "addMaskKeyframeAtPlayhead" | "addOpacityKeyframeAtPlayhead" | "toggleColorGradeKeyframeAtPlayhead" | "toggleChromaKeyKeyframeAtPlayhead";
  };
  agentWritable: boolean;
};

/** Display metadata is mandatory for numeric effects; native bounds/defaults stay above. */
export type EffectProposalNumber = {
  step: number;
  suffix: string;
  label?: string;
  /** display = native * scale + offset; both directions use this one declaration. */
  scale?: number;
  offset?: number;
};

export type EffectControlDefinition = EffectControlBase & (
  | { kind: "number"; proposal: EffectProposalNumber; min: number; max: number; identity: number; normalize: (value: unknown) => number }
  | { kind: "tuple"; min: number; max: number; identity: readonly [number, number, number, number]; normalize: (value: unknown) => number[] }
  | { kind: "enum"; values: readonly [string, ...string[]]; identity: string; normalize: (value: unknown) => string }
  | { kind: "color"; identity: string; normalize: (value: unknown) => string }
  /**
   * A list of numbers edited as one graph or wheel. `itemBounds` repeats across the list (a curve
   * alternates x and y); `lengths.multiple` keeps whole points. Empty `identity` means "no curve".
   */
  | { kind: "list"; identity: readonly number[]; lengths: { min: number; max: number; multiple: number }; itemBounds: readonly (readonly [number, number])[]; normalize: (value: unknown) => number[] }
);

const tupleMask = (value: unknown) => Array.isArray(value) && value.length === 4
  ? value.map((entry) => clampMaskInset(Number(entry)))
  : [0, 0, 0, 0];

